Q: How to capture process-space key events in OSX command-line tool, CoreFoundation, C API? A: <p>Here is a bit of individual research that resulted in 120 lines of functional code, which programmatically capture and possibly process keyboard events from the active terminal window running the command-line program. There is a block argument in dispatch_sync() function, which I don't particularly like, because it is a polluted C API (Apple specific extension to the C standard, AFAIK), but I haven't come upon an idea how to write that part in plain C elegantly, yet. The program compiles in gcc (macOS command-line tools) as well as in Xcode and runs in macOS 15.5, Arm64. More testing on other hardware and systems under way...</p>
<p>Here's the code. I don't how much of a decent programming practice it may be, yet I'd like to share it, at least for the reason that the question has not received a more straightforward answer so far:</p>
<pre><code>//  cfmn.c
//  gcc -Wall -o cfmn cfmn.c -framework ApplicationServices
//_______________________________________________________________________________

#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;
#include &lt;unistd.h&gt;
#include &lt;sys/types.h&gt;
#include &lt;ApplicationServices/ApplicationServices.h&gt;

static dispatch_queue_t  lock;
static CFMutableArrayRef events;

//_______________________________________________________________________________
CGEventRef callback(CGEventTapProxy proxy,
                    CGEventType type,
                    CGEventRef event,
                    void *refcon)
{
    CGEventFlags f = CGEventGetFlags(event);
    // Exclude command or control modifiers
    if (((f &amp; kCGEventFlagMaskCommand) == 0)&amp;&amp;((f &amp; kCGEventFlagMaskControl) == 0)) {
       if (type == kCGEventKeyDown) {
          CGKeyCode keyCode = (CGKeyCode)CGEventGetIntegerValueField(event, kCGKeyboardEventKeycode);
          printf (&quot;Key code: %d\n&quot;, keyCode);
          if (keyCode == 53)
              CFRunLoopStop(CFRunLoopGetCurrent());
          // unelegant part of code ...
          dispatch_sync(lock, ^{
              CFArrayAppendValue(events, event);
          });
          ;
       }
       return NULL; // do not return event
   }
   return event;    // return event unmodified
}
//_______________________________________________________________________

int main(int argc, const char * argv[]) {

        CFArrayRef windowList;
        char appname[256] = {0};    
        pid_t frontmostPid = 0;
        void* userinfo = NULL;
        CFRunLoopSourceRef runLoopSource;

        lock = dispatch_queue_create(&quot;lock&quot;, NULL);
        events = CFArrayCreateMutable(kCFAllocatorDefault,
                                      0,
                                      &amp;kCFTypeArrayCallBacks);


        windowList = CGWindowListCopyWindowInfo(kCGWindowListOptionOnScreenOnly, 
                           kCGNullWindowID);

          if (windowList != NULL) {
              CFIndex count = CFArrayGetCount(windowList);
              for (CFIndex i = 0; i &lt; count; i++) {
                  CFDictionaryRef windowInfo = CFArrayGetValueAtIndex(windowList, i);
                  CFNumberRef layerNum = CFDictionaryGetValue(windowInfo,
                                                         kCGWindowLayer);
                  int layer = 0;
                  if (layerNum &amp;&amp; CFNumberGetValue(layerNum, kCFNumberIntType, &amp;layer) &amp;&amp; layer == 0) {
                      CFNumberRef pidNum = CFDictionaryGetValue(windowInfo, kCGWindowOwnerPID);
                      if (pidNum) {
                          CFNumberGetValue(pidNum, kCFNumberIntType, &amp;frontmostPid);
                      }
                      CFStringRef ownerName = CFDictionaryGetValue(windowInfo, kCGWindowOwnerName);
                      if (ownerName) {
                          CFStringGetCString(ownerName,
                                          appname,
                                          sizeof(appname),
                                          kCFStringEncodingUTF8);
                      }
                      break;
                  }
              }
              CFRelease(windowList);
          }


        printf(&quot;\n|- - - - - Main Loop Test - - - - -|\n&quot;);
        printf(&quot;|- - press any key; &lt;esc&gt;=quit- - -|\n&quot;);
        printf(&quot;Frontmost App: %s;  &quot;,appname);
        printf(&quot;PID: %d\n&quot;,     frontmostPid );

        CGEventMask   eventMask = CGEventMaskBit(kCGEventKeyDown);

        CFMachPortRef eventPort = CGEventTapCreateForPid(frontmostPid,
                                                kCGHeadInsertEventTap,
                                                kCGEventTapOptionDefault,
                                                eventMask,
                                                callback,
                                                userinfo);
        if (eventPort == NULL) {
            fprintf(stderr, &quot;NULL event port\n&quot;);
            return 1;      
        }

        runLoopSource = CFMachPortCreateRunLoopSource( kCFAllocatorDefault, 
                                                      eventPort, 
                                                      0);
        CFRunLoopAddSource(CFRunLoopGetCurrent(), 
                           runLoopSource, 
                           kCFRunLoopCommonModes);
        CGEventTapEnable(eventPort, true);
        CFRunLoopRun();

        printf   (&quot;Program stopped\n\n&quot;);
        CFRelease(runLoopSource);
        CFRelease(eventPort);
        CFRelease(events);
        dispatch_release(lock);

    return 0;
}
</code></pre>

Q: expo run:androind ndk version cannot be changed A: <pre class="lang-js prettyprint-override"><code>import { withGradleProperties } from '@expo/config-plugins';

const withNdkVersion = (config) =&gt; {
    return withGradleProperties(config, (config) =&gt; {
        config.modResults.push({
            type: 'property',
            key: 'ndkVersion',
            value: '28.0.13004108',
        });
        return config;
    });
};
</code></pre>
<p>after that simply add the function to the plugins: [withNdkVersion,  ...others]<br />
this helped me i hope it helps you as well.</p>
<p>Also consider checking the file /node_modules/expo-modules-autolinking/android/expo-gradle-plugin/expo-autolinking-plugin/src/main/kotlin/expo/modules/plugin/ExpoRootProjectPlugin.kt as it will have the ndk version Fallback</p>

Q: Animation bug on list when entering edit mode with swipe to delete disabled A: <p>This problem is happening because the <code>.deleteDisabled</code> state is being changed <em>in reaction</em> to the edit state changing, by which time, the animation for the edit state is already underway. So the animation starts off with a red delete button in each row, but these buttons disappear after the animation has started, causing the jumpy movement.</p>
<p>A workaround is to disable delete on the rows <em>before</em> turning on edit mode. This can be done by using your own button to perform the state change, instead of an <code>EditButton</code>. Of course, it's never quite as easy as you might expect:</p>
<ul>
<li>A native <code>EditButton</code> changes appearance when active, so if you want the custom button to behave the same, you have to perform the change of appearance yourself.</li>
<li>When turning off edit mode, you have to wait for the animation to complete before enabling delete on the rows again, otherwise the red delete buttons become visible too early.</li>
</ul>
<p>A way to solve the last point is to use an enum with 3 cases to drive the change of mode. The extra enum case is an intermediate state that is used when turning off. The actual edit mode is turned off <code>withAnimation</code> and a <code>completion</code> closure is used to perform a follow-up update to the enum state.</p>
<p>Here is the updated example to show it working:</p>
<pre class="lang-swift prettyprint-override"><code>struct ContentView: View {
    enum EditPhase {
        case active
        case turningOff
        case inactive
    }
    @State private var items = [&quot;Item 1&quot;, &quot;Item 2&quot;, &quot;Item 3&quot;, &quot;Item 4&quot;, &quot;Item 5&quot;]
    @State private var selection: Set&lt;String&gt; = []
    @State private var editMode = EditMode.inactive
    @State private var editPhase = EditPhase.inactive

    var body: some View {
        NavigationStack {
            List(selection: $selection) {
                ItemsList(items: $items, isEditing: editPhase != .inactive)
            }
            .environment(\.editMode, $editMode)
            .toolbar {
                ToolbarItem(placement: .topBarLeading) {
                    if editPhase == .active {
                        Button(role: .confirm) {
                            editPhase = .turningOff
                        }
                    } else {
                        Button(&quot;Edit&quot;) {
                            if editPhase == .inactive {
                                withAnimation {
                                    editPhase = .active
                                }
                            }
                            // else... animation in progress, do nothing
                        }
                    }
                }
                ToolbarItem(placement: .topBarTrailing) {
                    if !selection.isEmpty {
                        Button(&quot;Delete&quot;, role: .destructive) {
                            items.removeAll { selection.contains($0) }
                            selection.removeAll()
                        }
                    }
                }
            }
            .task(id: editPhase) {
                if editPhase == .active {
                    withAnimation {
                        editMode = .active
                    }
                } else if editPhase == .turningOff {
                    withAnimation {
                        editMode = .inactive
                    } completion: {
                        editPhase = .inactive
                    }
                }
            }
        }
    }
}

private struct ItemsList: View {
    @Binding var items: [String]
    let isEditing: Bool

    var body: some View {
        ForEach(items, id: \.self) { item in
            Text(item)
        }
        .onDelete { offsets in
            items.remove(atOffsets: offsets)
        }
        .deleteDisabled(isEditing)
    }
}
</code></pre>
