Q: How can I create an Eq for an object with an optional property? A: <p>Only way I could make it work:</p>
<pre class="lang-js prettyprint-override"><code>import * as eq from 'fp-ts/Eq';
import type { ReadonlyRecord } from 'fp-ts/ReadonlyRecord';
import type { Simplify } from 'type-fest';

export const optionalEq = &lt;A&gt;(eqA: eq.Eq&lt;A&gt;): eq.Eq&lt;A | undefined&gt; =&gt;
    eq.fromEquals((a: A | undefined, b: A | undefined) =&gt; {
        if (a === undefined) {
            return b === undefined;
        }
        if (b === undefined) {
            return false;
        }

        return eqA.equals(a, b);
    });

type EqType&lt;A extends eq.Eq&lt;any&gt;&gt; = A extends eq.Eq&lt;infer B&gt; ? B : never;
export const optionalStructEq = &lt;A extends ReadonlyRecord&lt;string, eq.Eq&lt;any&gt;&gt;, Key extends keyof A&gt;(
    source: A,
    ...keys: Key[]
) =&gt; {
    const newSource: Record&lt;Key, eq.Eq&lt;any&gt;&gt; = { ...source };

    keys.forEach(key =&gt; {
        newSource[key] = optionalEq(source[key]);
    });

    const target = { ...source, ...newSource };

    return eq.struct(target) as eq.Eq&lt;
        Simplify&lt;
            { [K in Exclude&lt;keyof A, Key&gt;]: EqType&lt;A[K]&gt; } &amp; {
                [K in Key]?: EqType&lt;A[K]&gt;;
            }
        &gt;
    &gt;;
};

const tableColumnEq = optionalStructEq(
    {
        name: string.Eq,
        valueType: eq.struct({
            type: string.Eq,
        }),
        isSortable: boolean.Eq,
        isAlwaysVisible: boolean.Eq,
    },
    'isAlwaysVisible',
);

/*
const tableColumnEq: eq.Eq&lt;{
    name: string;
    valueType: {
        readonly type: string;
    };
    isSortable: boolean;
    isAlwaysVisible?: boolean | undefined;
}&gt;
*/
</code></pre>
